//! 🧪️ Actual three paged identities preserve Unicode semantics and original custody across paid assembly and cancellation.
use super::*;
use semio_framework_replication_ids::HybridLogicalTimestamp;
use crate::retained_sources::{stage,drained,polled,projected};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[derive(semio_framework_value::RetireOwned)]
struct Authority{actor:Text}
impl ArtifactCanonicalEditAuthority for Authority{fn sequence_number(&self)->i32{1}fn clock(&self)->HybridLogicalTimestamp{HybridLogicalTimestamp{actor:1,physical_ms:1,logical:1}}fn actor(&self)->&(dyn Utf8Text+Sync){&self.actor}fn line(&self)->Option<&(dyn Utf8Text+Sync)>{None}fn group(&self)->Option<&(dyn Utf8Text+Sync)>{None}}
fn grant(demand:RetirementDemand)->RetainedCloneGrant{assert!(demand.copy_bytes+demand.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}}
#[test]
fn canonical_native_identity_assembly_preserves_original_unicode_fields_and_exact_granted_cancellation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../🛍️products/💻️os/🔨️modules/🏪️store/📦️prepared/🪪️identity/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for repeats in [1,fixture["repeat"].as_u64().unwrap()as usize]{for pause in [Some(0),Some(1),Some(3),Some(17),Some(129),None]{
  let actor=fixture["actor"].as_str().unwrap().repeat(repeats);let id=fixture["id"].as_str().unwrap();let native=Authority{actor:actor.as_str().into()};let actor_pointer=native.actor.chunks().next().unwrap().as_ptr();let mut authority=stage(native);
  let mut edit=Box::new(Edit::<bool>{id:id.to_owned(),actor:None,line:None,sequence_number:1,forwards:vec![true],mutation_meta:Vec::new(),inverse:semio_framework_value::RetainedPublicationRoot::new(semio_framework_value_persistent::list::PagedList::new()),verb:None,started_at:String::new(),finished_at:None});edit.id.reserve(8192);let edit_pointer=edit.as_ref()as*const Edit<bool>;let id_pointer=edit.id.as_ptr();let mut edit=stage(edit);
  let original_authority=projected(authority.borrow().project(0,|value:&Authority|value as&dyn ArtifactCanonicalEditAuthority));let original_edit=projected(edit.borrow().project(0,|value:&Box<Edit<bool>>|value.as_ref()));
  let admitted=grant(ArtifactCanonicalEditIdentityCursor::<bool>::constructor_demand());let((mut cursor,receipt),heap)=observe(||ArtifactCanonicalEditIdentityCursor::admit(original_authority,original_edit,admitted).unwrap_or_else(|_|panic!("identity original admission")));assert!(receipt.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut turns=0;
  while !cursor.terminal_is_empty()&&!cursor.is_ready(){assert!(turns<100000);if pause==Some(turns){cursor.begin_close();}let(demand,heap)=observe(||cursor.next_demand().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let admitted=grant(demand);
   for refused in [RetainedCloneGrant::default(),RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..admitted}]{if refused==admitted{continue;}let(step,spent)=polled(refused,|effect|cursor.advance(effect));assert_eq!(step.progress(),Default::default());assert_eq!(spent,(0,0));}
   let(step,_)=polled(admitted,|effect|cursor.advance(effect));assert!(step.progress().fits(admitted));turns+=1;
  }
  if cursor.is_ready(){assert!(pause.is_none_or(|cut|cut>=turns));let original_pointers=cursor.output.as_ref().unwrap().each_ref().map(|value|value.chunks().next().unwrap().as_ptr());let admitted=grant(cursor.next_take_demand());let(take,heap)=observe(||cursor.take(RetainedCloneGrant::default()).unwrap());assert!(take.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let((output,receipt),heap)=observe(||cursor.take(admitted).unwrap().unwrap());assert!(receipt.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(output.each_ref().map(|value|value.chunks().next().unwrap().as_ptr()),original_pointers);assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::json!([actor,id,id]));let[a,b,c]=output;let mut output=stage((a,b,c));drained(&mut output);let(_,heap)=observe(||drop(output));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  assert!(cursor.terminal_is_empty());assert_eq!(authority.borrow().get().actor.chunks().next().unwrap().as_ptr(),actor_pointer);assert_eq!(edit.borrow().get().as_ref()as*const Edit<bool>,edit_pointer);assert_eq!(edit.borrow().get().id.as_ptr(),id_pointer);let(_,heap)=observe(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drained(&mut edit);drained(&mut authority);let(_,heap)=observe(||{drop(edit);drop(authority);});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }}
}
